from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
out=Path('leverans');d=Document();sec=d.sections[0];sec.page_width=Inches(8.5);sec.page_height=Inches(11)
sec.top_margin=sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.7)
for name in ['Normal','Title','Subtitle','Heading 1','Heading 2']:
 st=d.styles[name];st.font.name='Calibri';st.font.color.rgb=RGBColor(0,0,0)
d.styles['Normal'].font.size=Pt(11);d.styles['Normal'].paragraph_format.space_after=Pt(8)
d.styles['Title'].font.size=Pt(30);d.styles['Heading 1'].font.size=Pt(21);d.styles['Heading 2'].font.size=Pt(14)
sec.footer.paragraphs[0].text='Börscase 2.1  •  Funktioner och metoder  •  14 september 2026'
sec.footer.paragraphs[0].style=d.styles['Caption']
def p(t):d.add_paragraph(t)
def h(t):d.add_heading(t,2)
def pic(f,caption):
 d.add_picture(str(out/'skarmbilder'/f),width=Inches(7.05));d.add_paragraph(caption,'Caption')
def page(title):d.add_page_break();d.add_heading(title,1)
d.add_paragraph('Börscase funktioner och metoder','Title')
p('Den här guiden visar vad appen gör och hur den arbetar, med nio skärmbilder från den faktiska appen. Den är skriven för dig som vill förstå bolagen bakom aktierna och följa upp dina placeringsidéer. Börscase samlar kurser, rapportunderlag och nyckeltal i en lokal app, med länkar till källorna och en journal som bevarar tidigare analyser.')
h('Från bolagssiffror till en tydligare analys')
p('Se hur lönsamheten utvecklas, om vinsten blir kassaflöde och hur värderingen förhåller sig till bolagets resultat. Analysrummet förklarar begreppen där siffrorna visas, så att du kan lägga mer tid på frågorna som avgör ditt case.')
pic('01-kassaflode.png','Atlas Copco A i appen. Utsnitt av kassaflödesmått för helåret 2025, fångat den 14 september 2026. Historiskt exempel, ingen köpbedömning.')
h('En arbetsplats för hela ditt bolagscase')
p('Översikten hjälper dig att jämföra bolag. Analysrummet samlar nyckeltal, förändringar, rapportkällor, bevakningar, värderingsscenarier och din analysjournal. Svenska och amerikanska bolag ingår; tillgången till rapportdata varierar mellan bolagen.')
p('Nyttan är ett mer strukturerat och granskningsbart beslutsunderlag. Appens bolagsrangordning har inte visat någon säker överavkastning i de tester som genomförts.')
page('Multiplar och kassaflöde med förklaringar')
p('P/E, P/B, P/S, EV/EBIT och EV/EBITDA gör det möjligt att belysa värderingen från flera håll. I Analysrummet finns 27 nyckeltal med definitioner, beräkningar och källunderlag när uppgifterna är tillgängliga.')
pic('05-multiplar.png','Apple i Analysrummet. Historisk helårsvinst och sparat börsvärde; siffrorna är ett exempel från appen och ändras med underlaget.')
h('Följ pengarna genom verksamheten')
p('Kassaflöde från rörelsen, investeringar och fritt kassaflöde visar hur verksamheten finansierar sig. Marginaler, nettoskuld och soliditet kompletterar bilden. Utdelningen kan jämföras med både nettovinst och fritt kassaflöde när utdelningsdata finns.')
h('Förstå vad multipeln faktiskt mäter')
p('P/E här bygger på historisk vinst, inte analytikernas prognoser. Du kan välja senaste helår eller rullande tolv månader när fyra sammanhängande kvartal finns. P/B bygger på bokfört eget kapital och är inte ett beräknat substansvärde.')
p('I den äldre branschmodellen används inte P/E för fastighets- och investmentbolag. Analysrummet kan ändå visa ett historiskt P/E från underlaget, med en förklaring om värdeförändringar. Förvaltningsresultat och substansvärde behöver kompletteras från bolagets rapport.')
p('Saknade uppgifter visas öppet. Förlust ger inget positivt P/E, och bankanalysen utesluter vissa olämpliga mått. Organisk tillväxt, orderingång, konsensus och prognos-P/E hämtas inte automatiskt i denna version.')
page('Upptäck förändringar och gå till källan')
p('En ny rapport blir mer användbar när du kan jämföra den med föregående underlag. Börscase visar förändringar mellan bokslut och sparade analyser, med rapportperioder och länkar som hjälper dig att kontrollera uppgifterna.')
pic('02-kallor.png','Apple i vyn Förändringar och källor. Tabellen visar utveckling mellan årsboksluten och länkar till underlaget.')
h('Hitta det som förtjänar en närmare läsning')
p('Rapportanalysen kan lyfta textsignaler och nya eller omskrivna riskstycken när jämförbara rapporter finns. Du kan gå vidare till originalrapporten och bedöma sammanhanget. Textregler hittar signalerna; de är inte en fullständig automatisk granskning av bolaget.')
h('Gör din idé möjlig att följa upp')
p('I Ledning och bevakning kan du dokumentera vad som måste stämma i ditt case och sätta upp mätbara bevakningar. Journalen bevarar tidigare analyser, så att du kan återvända till vad du visste när du gjorde din bedömning.')
page('Pröva värderingen med egna antaganden')
p('Vilken tillväxt och marginal krävs för att motivera priset? Scenariovyn låter dig ändra antaganden om verksamheten och kapitalkostnaden och jämföra ett pessimistiskt, ett grundläggande och ett optimistiskt scenario.')
pic('03-scenarier.png','Scenariovyn med Apples underlag och redigerbara exempelantaganden. Inställningarna illustrerar funktionen och är inga prognoser.')
h('Se hur känslig slutsatsen är')
p('Beräkningen använder fem års kassaflöden och ett terminalvärde. En känslighetstabell visar hur värdet påverkas av marginal och kapitalkostnad. Appen visar också vilken tillväxt dagens pris skulle kräva med övriga antaganden oförändrade.')
p('Resultaten är räkneexempel som beror på dina antaganden. Modellen är förenklad och inte anpassad för banker. Den hjälper dig att pröva ett resonemang, men fastställer inte bolagets rätta värde.')
page('Bygg erfarenhet som går att utvärdera')
p('Analysjournalen ger appen ett minne. Sparade observationer kan följas upp efter 30, 90 och 365 dagar, med jämförelseindex och en schablonkostnad. Det gör det möjligt att undersöka vilka samband som håller över tid.')
pic('04-journal.png','Journal och lärande vid dokumentets tillkomst. Appen väntar ännu på tillräckliga framtida utfall för modellträning.')
h('Lärandet behöver verkliga resultat')
p('Träning kräver minst 120 kompletta observationer från 12 startmånader och 90 dagars facit. En modell utvärderas i tidsordning och kör i skuggläge utan att ändra råden. Detta är en funktion för prövning av modeller, inte ett löfte om att appen automatiskt blir bättre på att välja aktier.')
h('Kom igång på din egen dator')
p('Packa upp ZIP-filen. Med Python 3.10 eller senare installerat kör du INSTALLERA.bat, sedan SKANNA.bat och STARTA_APP.bat. Internet behövs för installation och datahämtning. Appen öppnas i webbläsaren och körs lokalt.')
p('Paketet innehåller kod och startfiler. Din journal, egna bolagsinställningar och hämtade bolagsdata följer inte med. Läs ANALYSRUM.md för handhavande och LICENS.txt för villkor. Nuvarande licens gäller privat, icke kommersiell användning.')

page('Så hämtas rapporter och siffror')
p('När du hämtar en ny analys samlar appen två olika underlag: själva rapporttexten och strukturerade bokslutssiffror. Nyckeltalen läses alltså inte generellt ut ur de PDF-sidor som textanalysen använder.')
h('Från datakälla till sparad analys')
p('1. Bolagets symbol kopplas till datakällan. För USA hämtas inlämningar från SEC EDGAR via bolagets CIK-nummer. Textanalysens standardrapport är 10-K, den amerikanska årsrapporten.')
p('2. För svenska bolag söker appen rapportmeddelanden och PDF-länkar via MFN. PDF-texten extraheras med pypdf. Inskannade sidor utan läsbar text kan inte analyseras med den här metoden; appen har ingen inbyggd OCR.')
p('3. Kurser och marknadsdata hämtas via Yahoo Finance och yfinance. Bokslut hämtas från Yahoo och, för bolag med EDGAR-stöd, SEC Company Facts i XBRL-format. SEC prioriteras och Yahoo kan fylla saknade fält för samma bokslutsdatum. Valutakrock ger en separat återgång till Yahoo-underlag.')
p('4. Data normaliseras, nyckeltal räknas ut och rapporttexten jämförs. Hämtade svar kan återanvändas från lokal cache. En ny analys betyder därför inte att varje källa laddas ner på nytt eller att alla kurser är i realtid.')
p('5. Analysen sparas i den lokala journalen med observationstid. Vyerna visar resultatet, tillgängliga källor och jämförelser. Bevakningar bedöms mot den sparade analysen när de visas.')
pic('08-berakning.png','Beräkning och källa är öppnad för Apples fria kassaflöde. Här syns både formeln och underlaget för dess två delar.')
page('Så mäts förändringar i rapporttexten')
p('Appen räknar ord och använder fasta regler. Det gör beräkningen möjlig att upprepa, men innebär också att den inte förstår alla betydelser, reservationer och samband i texten.')
pic('09-rapportmetod.png','Rapporten i detalj visar textlikhet och andelar ord. Exemplet gäller Apples sparade årsrapporter.')
h('Cosinuslikhet och Jaccard')
p('Texten delas upp i ord och blir en tabell över ordfrekvenser. Cosinuslikhet jämför frekvensmönstren på en skala upp till 1. Ett värde nära 1 betyder liknande ordanvändning; det bevisar inte att meningarna är identiska. Jaccard beräknas också och mäter överlapp mellan mängderna av olika ord.')
h('Finansiella ordlistor')
p('Tonläget mäts som andelen ord som finns i listor för bland annat negativitet, osäkerhet och tvister. Engelskan använder delmängder av Loughran–McDonalds kategorier; svenskan har egna, kortare listor. Jämför främst samma bolag, språk och rapportavsnitt över tid.')
p('Likhetsgränserna är appens fasta tumregler. En hög likhet kan dölja en viktig ändring i ett enda stycke. En låg likhet kan bero på ny disposition eller bristfällig textutvinning. Metoden behöver alltid läsas tillsammans med originaltexten.')
page('Så väljs jämförelsen och riskstyckena')
p('För amerikanska 10-K-rapporter jämförs den senaste hämtade rapporten med föregående rapport av samma form. Rubrikregler försöker avgränsa riskavsnitt och ledningens analys. Hela rapporten får också separata mått.')
p('För svenska rapporter väljs samma språk och den rapport som ligger närmast tolv månader tidigare, inom ett fönster på tio till fjorton månader. Det är en datumregel, inte en fullständig kontroll av att rapporttyper och verksamhetsperioder är identiska. Kontrollera därför rapporternas titlar.')
pic('06-riskstycken.png','Textförändringar med länk till originalrapporten. Inga textflaggor och nya riskstycken kan förekomma samtidigt eftersom de mäts med olika metoder.')
h('Nya eller omskrivna stycken')
p('Varje aktuellt stycke jämförs med föregående texts stycken. Om bästa cosinuslikheten är under 0,55 väljs stycket som kandidat. Korta stycken, vissa biografier och siffertunga stycken filtreras bort. Upp till åtta kandidater returneras. För USA används hittade riskavsnitt; den svenska funktionen söker kandidater i hela rapporttexten.')
h('Röda flaggor med sökmönster')
p('Reguljära uttryck söker särskilda formuleringar, exempelvis om fortsatt drift, intern kontroll och lånevillkor. Vissa mönster kontrollerar negationer nära träffen. Citat och vikt följer med. Metoden kan missa omformuleringar och ge felträffar; frånvaro av träff är inte bevis för att bolaget saknar risker.')
page('Från ett uttalande till en bevakning')
p('Appen letar efter meningar med ord som signalerar framtid, mål eller förväntan. Träffarna är förslag att läsa, inte automatiskt verifierade ledningslöften. Även allmänna risktexter och standardformuleringar kan fångas upp, vilket syns i exemplet.')
pic('07-bevakning.png','Ledning och bevakning. Användaren väljer vilket uttalande som är relevant och anger ett mätbart villkor. Inga demonstrationsvillkor har sparats i journalen.')
h('Gör villkoret kontrollerbart')
p('Välj ett mått, ett gränsvärde och om utfallet ska vara minst eller högst gränsen. Ett ledningsmål behöver även källhänvisning och målperiod. Andelar anges som decimaltal, till exempel 0,15 för 15 procent. Belopp anges i rapportvalutans hela enheter.')
h('Vad händer när nya siffror finns')
p('En investeringstes prövas mot tillgängliga sparade siffror. Ett ledningsmål väntar på ett bokslut med exakt det angivna slutdatumet. Därefter visas uppfyllt eller ej uppfyllt. Saknat mått ger okänd status. Appen försöker inte gissa att ett kvalitativt löfte har infriats.')
p('Bevakning här betyder uppföljning i appen. Detta är inte en aktiverad tjänst som automatiskt skickar e-post eller kontinuerligt övervakar nya rapporter i bakgrunden.')
page('Tre jämförelser och en modell under prövning')
h('Bokslut mot bokslut')
p('Förändringsvyn jämför de senaste tillgängliga årsboksluten: skillnad i belopp och procentuell förändring när jämförelsevärdet är positivt. I nyckeltalsvyn visas marginalförändringar i procentenheter. Rullande tolv månader kräver fyra sammanhängande kvartal; appen ersätter inte saknade kvartal med ett helår utan att säga till.')
h('Sparad analys mot sparad analys')
p('Journaljämförelsen visar vad som ändrats sedan föregående sparade observation. Det kan vara ny kurs, ny rapport eller reviderat underlag. En ändrad siffra behöver därför inte betyda att bolagets verksamhet förändrats just den dagen.')
h('Bolag mot andra bolag')
p('Poängmodellen rangordnar mått till percentiler och väger ihop dem i pelare för kvalitet, värdering, finansiell styrka, tillväxt, marknad och rapportsignaler. Jämförelsegrupper används där de har minst åtta bolag; mindre grupper jämförs bredare. Banker har särskilda mått. Saknade värden minskar täckningen, och vissa varningar ger poängavdrag. Poängen är en relativ rangordning, inte en sannolikhet för uppgång.')
h('Hur lärandet är konstruerat')
p('Den framtida skuggmodellen använder ridge-regression: en linjär modell med en straffterm som dämpar stora vikter. Variablerna standardiseras och extremvärden begränsas. Modellen tränas mot uppmätt överavkastning efter 90 dagar, med fast straffparameter 10.')
p('Tester sker i tidsordning. Endast observationer vars utfall avslutats före teststart får ingå i träningen. Prognosfelet jämförs med en baslinje som gissar noll överavkastning. Ett bootstrap-intervall beräknas över testmånadernas förbättringar. Resultatet ändrar inte appens råd; användaren startar uppföljningen och modellen väntar tills datakraven är uppfyllda.')
h('Underlag för metodbeskrivningen')
p('Beskrivningen är kontrollerad mot denna installations kod: datakallor.py, fundamenta.py, rapportlasning.py, svenska_rapporter.py, nyckeltal.py, case.py, intel.py och intel_api.py. Alla skärmbilder är från den lokala appen den 14 september 2026. Källkodens beräkningar beskrivs här; detta är inte en oberoende validering av metodernas investeringsresultat.')

